package com.ias.identity.bootstrap;

import org.junit.jupiter.api.*;
import java.sql.*;
import java.lang.reflect.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

/** Actual H2 physical JDBC transactions; connection faults are controlled wrappers, not physical MySQL failure. */
public class ConfigureFinanceCustomerTest {
 String url;Connection keeper;
 public static Timestamp utc(int precision){return Timestamp.from(Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS));}
 @BeforeEach void prepare()throws Exception{
  url="jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";keeper=connection();
  try(var s=keeper.createStatement()){
   s.execute("CREATE ALIAS UTC_TIMESTAMP FOR 'com.ias.identity.bootstrap.ConfigureFinanceCustomerTest.utc'");
   s.execute("CREATE TABLE tenant(id BIGINT PRIMARY KEY,code_normalized VARCHAR(32),status INT)");
   s.execute("CREATE TABLE identity_user(id BIGINT PRIMARY KEY,tenant_id BIGINT,realm VARCHAR(20),identity_type VARCHAR(20),status INT,binding_state INT,must_change_password INT,row_version BIGINT,security_version BIGINT,password_verifier VARCHAR(100),updated_at TIMESTAMP(3))");
   s.execute("CREATE TABLE identity_user_capability(user_id BIGINT,capability_code VARCHAR(50),enabled INT,row_version BIGINT DEFAULT 0,created_at TIMESTAMP(3),updated_at TIMESTAMP(3),PRIMARY KEY(user_id,capability_code))");
   s.execute("CREATE TABLE identity_configuration_operation(operation_id VARCHAR(36) PRIMARY KEY,request_digest VARCHAR(64),result_json VARCHAR(8192),created_at TIMESTAMP(3))");
   s.execute("CREATE TABLE identity_security_audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,occurred_at TIMESTAMP(3),action VARCHAR(48),actor_type VARCHAR(20),target_type VARCHAR(20),target_id BIGINT,tenant_id BIGINT,result VARCHAR(20),reason_code VARCHAR(48),user_security_version_before BIGINT,user_security_version_after BIGINT,trace_id VARCHAR(36))");
   s.execute("INSERT INTO tenant VALUES(7,'IAS_A',1),(8,'IAS_B',1)");
   s.execute("INSERT INTO identity_user VALUES(41,7,'TENANT','CUSTOMER',1,2,0,3,9,'original-verifier',CURRENT_TIMESTAMP),(42,7,'TENANT','CUSTOMER',1,2,0,5,2,'second-verifier',CURRENT_TIMESTAMP),(51,7,'TENANT','EMPLOYEE',1,0,0,1,1,'employee-verifier',CURRENT_TIMESTAMP),(61,NULL,'PLATFORM','PLATFORM',1,0,0,1,1,'platform-verifier',CURRENT_TIMESTAMP),(71,8,'TENANT','CUSTOMER',1,2,0,1,1,'foreign-verifier',CURRENT_TIMESTAMP)");
  }
 }
 @AfterEach void close()throws Exception{keeper.close();}
 Connection connection()throws SQLException{return DriverManager.getConnection(url,"sa","");}
 ConfigureFinanceCustomerMain.Customer customer(String user,String version,boolean read,boolean confirm){return new ConfigureFinanceCustomerMain.Customer(user,version,Map.of("finance.quote.read",read,"finance.quote.confirm",confirm));}
 ConfigureFinanceCustomerMain.Plan plan(String operation,String version,boolean read,boolean confirm){return new ConfigureFinanceCustomerMain.Plan(operation,"IAS_A",List.of(customer("41",version,read,confirm)));}
 String op(){return UUID.randomUUID().toString();}
 Map<String,Object> run(ConfigureFinanceCustomerMain.Plan p,boolean execute)throws Exception{try(var c=connection()){return ConfigureFinanceCustomerMain.configure(c,p,execute);}}
 long scalar(String sql)throws Exception{try(var c=connection();var s=c.createStatement();var r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
 String password()throws Exception{try(var c=connection();var s=c.createStatement();var r=s.executeQuery("SELECT password_verifier FROM identity_user WHERE id=41")){r.next();return r.getString(1);}}
 void sql(String sql)throws Exception{try(var c=connection();var s=c.createStatement()){s.execute(sql);}}
 void untouched()throws Exception{assertEquals(3,scalar("SELECT row_version FROM identity_user WHERE id=41"));assertEquals(9,scalar("SELECT security_version FROM identity_user WHERE id=41"));assertEquals(0,scalar("SELECT COUNT(*) FROM identity_user_capability"));assertEquals(0,scalar("SELECT COUNT(*) FROM identity_security_audit"));assertEquals("original-verifier",password());}
 @Test void dryRunValidatesWritesThenRollsBackAndNeverChangesPassword()throws Exception{var result=run(plan(op(),"3",true,true),false);assertEquals("DRY_RUN",result.get("state"));untouched();assertEquals(0,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));}
 @Test void explicitGrantAndOriginalUuidReplayHaveOneOperationAuditAndVersionAdvance()throws Exception{var p=plan(op(),"3",true,true);var one=run(p,true);assertEquals(one,run(p,true));assertEquals("COMMITTED",one.get("state"));assertEquals(4,scalar("SELECT row_version FROM identity_user WHERE id=41"));assertEquals(10,scalar("SELECT security_version FROM identity_user WHERE id=41"));assertEquals(2,scalar("SELECT COUNT(*) FROM identity_user_capability WHERE enabled=1"));assertEquals(1,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));assertEquals(1,scalar("SELECT COUNT(*) FROM identity_security_audit"));assertEquals("original-verifier",password());}
 @Test void explicitFalseRevokesOnlyTheseCapabilitiesWithoutChangingPasswordOrRoles()throws Exception{run(plan(op(),"3",true,true),true);sql("INSERT INTO identity_user_capability(user_id,capability_code,enabled) VALUES(41,'unrelated.customer.cap',1)");run(plan(op(),"4",false,false),true);assertEquals(0,scalar("SELECT COUNT(*) FROM identity_user_capability WHERE capability_code IN('finance.quote.read','finance.quote.confirm') AND enabled=1"));assertEquals(1,scalar("SELECT enabled FROM identity_user_capability WHERE capability_code='unrelated.customer.cap'"));assertEquals(5,scalar("SELECT row_version FROM identity_user WHERE id=41"));assertEquals(11,scalar("SELECT security_version FROM identity_user WHERE id=41"));assertEquals("original-verifier",password());}
 @Test void employeePlatformForeignTenantAndIncompleteOrRestrictedCustomerAreRejected()throws Exception{
  for(String user:List.of("51","61","71")){var p=new ConfigureFinanceCustomerMain.Plan(op(),"IAS_A",List.of(customer(user,"1",true,true)));assertThrows(Exception.class,()->run(p,true));}
  for(String change:List.of("status=0","binding_state=1","must_change_password=1","realm='PLATFORM'")){sql("UPDATE identity_user SET status=1,binding_state=2,must_change_password=0,realm='TENANT' WHERE id=41");sql("UPDATE identity_user SET "+change+" WHERE id=41");assertThrows(Exception.class,()->run(plan(op(),"3",true,true),true));}untouched();
 }
 @Test void disabledTenantAndWrongVersionOrOverflowCannotMutate()throws Exception{sql("UPDATE tenant SET status=0 WHERE id=7");assertThrows(Exception.class,()->run(plan(op(),"3",true,true),true));sql("UPDATE tenant SET status=1 WHERE id=7");assertThrows(Exception.class,()->run(plan(op(),"2",true,true),true));untouched();sql("UPDATE identity_user SET security_version=9223372036854775807 WHERE id=41");assertThrows(Exception.class,()->run(plan(op(),"3",true,true),true));assertEquals(0,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));}
 @Test void originalUuidDifferentBodyCannotChangeGrant()throws Exception{String key=op();run(plan(key,"3",true,true),true);assertThrows(Exception.class,()->run(plan(key,"3",true,false),true));assertEquals(4,scalar("SELECT row_version FROM identity_user WHERE id=41"));assertEquals(1,scalar("SELECT COUNT(*) FROM identity_security_audit"));}
 @Test void sameConfigurationOperationNamespaceCannotOverwriteOtherToolReceipt()throws Exception{String key=op();sql("INSERT INTO identity_configuration_operation VALUES('"+key+"','other-tool','{}',CURRENT_TIMESTAMP)");assertThrows(Exception.class,()->run(plan(key,"3",true,true),true));untouched();assertEquals(1,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));}
 @Test void auditFailureRollsBackCapabilitiesVersionsAndOperationThenOriginalKeyRecovers()throws Exception{String key=op();sql("ALTER TABLE identity_security_audit ADD CONSTRAINT qa_cap_audit CHECK(target_id<>41)");assertThrows(Exception.class,()->run(plan(key,"3",true,true),true));untouched();assertEquals(0,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));sql("ALTER TABLE identity_security_audit DROP CONSTRAINT qa_cap_audit");run(plan(key,"3",true,true),true);assertEquals(4,scalar("SELECT row_version FROM identity_user WHERE id=41"));assertEquals(1,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));}
 @Test void multiCustomerValidationFailureCannotPartiallyApplyEarlierCustomer()throws Exception{var p=new ConfigureFinanceCustomerMain.Plan(op(),"IAS_A",List.of(customer("41","3",true,true),customer("42","0",true,true)));assertThrows(Exception.class,()->run(p,true));untouched();assertEquals(0,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));}
 @Test void validationRejectsWriteCapabilityMissingExplicitFlagsDuplicatesAndConfirmWithoutRead(){var bad=new ConfigureFinanceCustomerMain.Customer("41","3",Map.of("finance.quote.read",true,"finance.quote.write",true));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.validate(new ConfigureFinanceCustomerMain.Plan(op(),"IAS_A",List.of(bad))));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.validate(plan(op(),"3",false,true)));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.validate(new ConfigureFinanceCustomerMain.Plan(op(),"IAS_A",List.of(customer("41","3",true,true),customer("41","3",true,true)))));}
 record Probe(Connection proxy,AtomicInteger aborts,AtomicInteger restores){}
 Probe failureConnection(boolean rollbackFailure,boolean commitBeforeFailure,boolean commitAfterFailure,boolean abortFailure)throws Exception{var target=connection();var aborts=new AtomicInteger();var restores=new AtomicInteger();var proxy=(Connection)Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{Connection.class},(p,m,args)->{
  if(m.getName().equals("setAutoCommit")&&Boolean.TRUE.equals(args[0]))restores.incrementAndGet();
  if(m.getName().equals("rollback")&&rollbackFailure)throw new SQLException("controlled rollback failure","08006");
  if(m.getName().equals("commit")&&commitBeforeFailure)throw new SQLException("controlled commit failure","08006");
  if(m.getName().equals("commit")&&commitAfterFailure){target.commit();throw new SQLException("controlled ACK lost","08006");}
  if(m.getName().equals("abort")){aborts.incrementAndGet();if(abortFailure)throw new SQLException("controlled abort failure","08006");target.close();return null;}
  try{return m.invoke(target,args);}catch(InvocationTargetException e){throw e.getCause();}
 });return new Probe(proxy,aborts,restores);}
 @Test void uncertainRollbackAbortsWithoutRestoringAndLeavesNoPartialGrant()throws Exception{var p=failureConnection(true,false,false,false);try{assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.configure(p.proxy(),plan(op(),"2",true,true),true));assertEquals(1,p.aborts().get());assertEquals(0,p.restores().get());untouched();}finally{p.proxy().close();}}
 @Test void commitFailureAbortsEvenAfterSuccessfulRollbackWithoutRestoring()throws Exception{var p=failureConnection(false,true,false,false);try{assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.configure(p.proxy(),plan(op(),"3",true,true),true));assertEquals(1,p.aborts().get());assertEquals(0,p.restores().get());untouched();}finally{p.proxy().close();}}
 @Test void committedButAckLostRecoversOriginalReceiptWithoutDoubleAuditOrVersion()throws Exception{String key=op();var command=plan(key,"3",true,true);var p=failureConnection(false,false,true,false);try{assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.configure(p.proxy(),command,true));assertEquals(1,p.aborts().get());assertEquals(0,p.restores().get());}finally{p.proxy().close();}assertEquals("COMMITTED",run(command,true).get("state"));assertEquals(4,scalar("SELECT row_version FROM identity_user WHERE id=41"));assertEquals(1,scalar("SELECT COUNT(*) FROM identity_configuration_operation"));assertEquals(1,scalar("SELECT COUNT(*) FROM identity_security_audit"));}
 @Test void failedRollbackAndAbortNeverRestoreOrReuseUncertainConnection()throws Exception{var p=failureConnection(true,false,false,true);try{assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.configure(p.proxy(),plan(op(),"2",true,true),true));assertEquals(1,p.aborts().get());assertEquals(0,p.restores().get());assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.configure(p.proxy(),plan(op(),"3",true,true),true));assertEquals(0,p.restores().get());}finally{p.proxy().close();}untouched();}
 @Test void cliPlanRejectsCoercedFlagsNumbersUnknownFieldsAndDuplicateJson(){var p=plan(op(),"3",true,true);String json=com.ias.trust.Chain.JSON.writeValueAsString(p);assertEquals(p,ConfigureFinanceCustomerMain.parsePlan(json));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.parsePlan(json.replace("\"finance.quote.read\":true","\"finance.quote.read\":\"true\"")));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.parsePlan(json.replace("\"finance.quote.read\":true","\"finance.quote.read\":1")));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.parsePlan(json.replace("\"userId\":\"41\"","\"userId\":41")));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.parsePlan(json.replace("\"finance.quote.read\":true","\"finance.quote.read\":true,\"finance.quote.read\":false")));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.parsePlan(json+" {}"));assertThrows(Exception.class,()->ConfigureFinanceCustomerMain.parsePlan(json.replace("\"tenantCode\"","\"unknownTenant\"")));}}
